export const VERSION=3, GRID=9, LIMIT=1200, PART_LIMIT=32, MASS_LIMIT=360, WEAPON_LIMIT=8, LEVELS=3, LAYER_HEIGHT=1.65;
// A modest durability pass gives damaged systems time to degrade visibly before
// they disappear. Costs and offensive output stay unchanged, so the extra time
// comes from survivability rather than a damage race.
export const HP_SCALE=1.15;
// Shared resource thresholds. The engine, workshop report, and HUD use the
// same bands so players can see the penalty before a weapon locks out.
export const HEAT_CAUTION=60, HEAT_DANGER=85, HEAT_LIMIT=100, HEAT_RECOVERY=35;
export const POWER_CAUTION=.3, POWER_CRITICAL=.12;
// Two matching weapons retain their normal cycle. Further matching weapons
// share targeting, ammunition and heat-control bandwidth, so a pure weapon
// bank remains a deliberate redundancy choice rather than the only answer.
export const DUPLICATE_WEAPON_FREE=2, DUPLICATE_WEAPON_RELOAD_PENALTY=.18;

export const MAX_MODULES=GRID*GRID*LEVELS;
export const DEFAULT_RULES=Object.freeze({mode:'standard',credits:1200,parts:32,mass:360,weapons:8,combat:'auto'});
export const OBJECTIVES=Object.freeze([{id:'reactor',name:'Reactor control',desc:'Hold the central reactor for energy and outlast the rival.'},{id:'escort',name:'Escort convoy',desc:'Keep your convoy alive and escort it to the far extraction gate.'}]);
export function normalizeRules(input=DEFAULT_RULES){
 if(typeof input==='number')input={...DEFAULT_RULES,mode:input===1200?'standard':'custom',credits:input};
 if(!input||typeof input!=='object'||Array.isArray(input)||!['standard','custom','unlimited'].includes(input.mode)||!['command','auto'].includes(input.combat))throw Error('Invalid match rules.');
 // Legacy command challenges remain importable; this edition is engineering-only.
 const r={mode:input.mode,combat:'auto'};
 for(const [k,max] of [['credits',1000000],['parts',MAX_MODULES],['mass',100000],['weapons',MAX_MODULES]]){const value=input[k];if(value!==null&&(!Number.isInteger(value)||value<1||value>max))throw Error('Invalid '+k+' limit.');r[k]=input.mode==='unlimited'?null:value;}
 if(r.mode==='standard'&&['credits','parts','mass','weapons'].some(k=>r[k]!==DEFAULT_RULES[k]))throw Error('Standard rules use the standard limits.');
 return r;
}
export function limitIssues(machine,rules=DEFAULT_RULES){const r=normalizeRules(rules),s=stats(machine),out=[];if(r.credits!==null&&s.cost>r.credits)out.push('Over budget by '+(s.cost-r.credits)+' credits.');if(r.parts!==null&&s.parts>r.parts)out.push('Remove '+(s.parts-r.parts)+' fitted parts to meet the '+r.parts+'-part limit.');if(r.mass!==null&&s.mass>r.mass)out.push('Over the '+r.mass+'-tonne mass limit by '+(s.mass-r.mass)+' t.');if(r.weapons!==null&&s.weapons>r.weapons)out.push('A maximum of '+r.weapons+' weapons can be fitted.');return out;}
export function rulesLabel(rules){const r=normalizeRules(rules);if(r.mode==='unlimited')return 'UNLIMITED \xB7 243 build sockets';return (r.credits===null?'Unlimited credits':r.credits.toLocaleString()+' credits')+' \xB7 '+(r.parts===null?'\u221E fitted parts + core':r.parts+' fitted parts + core')+' \xB7 '+(r.mass===null?'\u221E':r.mass)+' t \xB7 '+(r.weapons===null?'\u221E':r.weapons)+' weapons';}

export const keyOf=m=>m.x+','+m.y+','+(m.z||0);
export const PATTERNS=['solid','racing','hazard','camo'];
